/** every logo name, for directories and pickers */
export const BRAND_LOGO_NAMES = Object.keys(LOGOS) as BrandLogoName[];
export function brandTitle(name: BrandLogoName): string {
  return LOGOS[name].title;
}
export function BrandLogo({ name, size = 20, className = "", style }: { name: BrandLogoName; size?: number; className?: string; style?: CSSProperties }) {
  const logo = LOGOS[name];
  const draw = (v: Variant, variant: "light" | "dark") => (
    <svg
      key={variant}
      viewBox={v.viewBox}
      width={size}
      height={size}
      role="img"
      aria-label={logo.title}
      className={`brand-logo brand-logo-${variant} ${logo.dark ? "brand-logo-has-dark" : ""} shrink-0 ${className}`}
      style={style}
      /* static, vendored, namespaced markup — not user content */
      dangerouslySetInnerHTML={{ __html: v.body }}
    />
  );
  return logo.dark ? <>{draw(logo.light, "light")}{draw(logo.dark, "dark")}</> : draw(logo.light, "light");
}
